"""SQLite → PostgreSQL 数据搬运（可重复运行）。

## 用法

    python scripts/migrate_to_pg.py                    # 搬运 + 对账
    python scripts/migrate_to_pg.py --verify-only      # 只对账，不写库
    python scripts/migrate_to_pg.py --tables policy translation
    python scripts/migrate_to_pg.py --db path/to.db    # 指定源库

## 设计

* **可重复**：每张表先 ``TRUNCATE`` 再灌 —— 跑到一半失败可以整只重跑，
  不会出现"灌了一半、剩下一半是旧的"这种最难查的状态。
* **保留原 id**：schema 用 ``GENERATED BY DEFAULT AS IDENTITY``（ALTER 过），
  允许显式插入；导入后 **必须重置序列**，否则后续 INSERT 会撞主键。
* **逐表对账**：行数 + **全表逐列 md5**（按主键排序，两边同一套算法）。
  不只看行数 —— 行数相同而内容是别人的，才是真正可怕的情形。
* 全程不走 subprocess，直接用 psycopg 写 PG。

## 时机

生产仍在 SQLite 上跑（翻译工作流），数据每天在变，所以本脚本交付的是
**可重复运行的搬运能力**；真正执行在 launch 的停机窗口重跑一次。
"""
from __future__ import annotations

import argparse
import hashlib
import sqlite3
import sys
import time
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parents[1] / "src"))

from taxassist.config import DB_PATH  # noqa: E402

# 要搬的表。顺序按依赖关系排（先政策，再挂靠它的东西）。
# 视图 policy_official 不搬（它是查询，不是数据）。
TABLES = [
    "policy",
    "raw_snapshot",
    "fetch_log",
    "attachment",
    "policy_relation",
    "translation",
    "translation_ai_review",
    "translation_review",
    "app_user",
    "invite_code",
    "customer",
    "api_key",
    "usage_log",
    "meta",
]

def order_key(sc: sqlite3.Connection, table: str, cols: list[str]) -> str:
    """确定对账用的稳定排序。

    各表主键形态不同（policy 是 ``id``，app_user 是 ``username``，
    customer 是 ``name``，api_key 是 ``key_hash``，meta 是 ``key``）——
    不写死，直接问 SQLite。没有主键的表退化为按全部列排序（确定且唯一）。
    """
    info = list(sc.execute(f"PRAGMA table_info({table})"))
    pk = [r[1] for r in info if r[5]]
    if pk:
        return ", ".join(f'"{c}"' for c in pk)
    return ", ".join(f'"{c}"' for c in cols)


#: 每张表声明为 identity 的列（导入后要 setval 重置序列）。
IDENTITY_COL = "id"


def _dsn() -> str:
    import os

    return os.environ.get("TAXASSIST_PG_DSN") or "host=127.0.0.1 dbname=taxassist user=taxassist"


def _val(v) -> str:
    """把值渲染成对账用的规范字符串（两边必须完全一致）。

    None 用 ``\\N``（与 COPY 的 NULL 记法一致，避免与空串混淆 ——
    'NULL' 和 '' 是两回事，混起来对账就等于没对）。
    """
    if v is None:
        return "\\N"
    if isinstance(v, (bytes, bytearray)):
        return v.hex()
    return str(v)


def _row_hash(parts: list[str]) -> str:
    h = hashlib.md5()
    h.update("|".join(parts).encode("utf-8", "surrogatepass"))
    h.update(b"\n")
    return h.hexdigest()


def _digest(rows, cols, limit: int | None = None) -> tuple[str, int]:
    """流式计算全表摘要，同时数行数（避免两次遍历）。"""
    h = hashlib.md5()
    n = 0
    for row in rows:
        if limit is not None and n >= limit:
            break
        h.update(_row_hash([_val(row[c]) for c in cols]).encode())
        n += 1
    return h.hexdigest(), n


# ------------------------------------------------------------------ 结构


def sqlite_tables(sc: sqlite3.Connection) -> list[str]:
    have = {r[0] for r in sc.execute(
        "SELECT name FROM sqlite_master WHERE type='table'").fetchall()}
    return [t for t in TABLES if t in have]


def sqlite_columns(sc: sqlite3.Connection, table: str) -> list[str]:
    return [r[1] for r in sc.execute(f"PRAGMA table_info({table})").fetchall()]


def pg_columns(pc, table: str) -> list[str]:
    with pc.cursor() as cur:
        cur.execute(
            "SELECT column_name FROM information_schema.columns"
            " WHERE table_schema='public' AND table_name=%s ORDER BY ordinal_position",
            (table,))
        return [r["column_name"] for r in cur.fetchall()]


# ------------------------------------------------------------------ 搬运


def truncate(pc, table: str) -> None:
    with pc.cursor() as cur:
        cur.execute(f'TRUNCATE TABLE "{table}" RESTART IDENTITY CASCADE')


def copy_table(sc, pc, table: str, cols: list[str], batch: int = 2000) -> int:
    """逐批灌入。用 executemany 而不是 COPY —— 类型推断的坑不值得踩。"""
    marks = ",".join(["%s"] * len(cols))
    names = ",".join(f'"{c}"' for c in cols)
    sql = f'INSERT INTO "{table}" ({names}) VALUES ({marks})'
    order = order_key(sc, table, cols)
    total = 0
    with pc.cursor() as cur:
        batch_rows: list[tuple] = []
        for row in sc.execute(f'SELECT {",".join(cols)} FROM "{table}" ORDER BY {order}'):
            batch_rows.append(tuple(row))
            if len(batch_rows) >= batch:
                cur.executemany(sql, batch_rows)
                total += len(batch_rows)
                batch_rows.clear()
        if batch_rows:
            cur.executemany(sql, batch_rows)
            total += len(batch_rows)
        pc.commit()
    return total


def reset_sequence(pc, table: str, col: str = IDENTITY_COL) -> None:
    """把 identity 序列推到 MAX(列) —— 不做这一步，之后第一条 INSERT 就撞主键。"""
    with pc.cursor() as cur:
        cur.execute(
            "SELECT pg_get_serial_sequence(%s, %s) AS seq", (table, col))
        row = cur.fetchone()
        seq = row["seq"] if row else None
        if not seq:
            return
        cur.execute(f'SELECT COALESCE(MAX("{col}"), 0) AS m FROM "{table}"')
        mx = cur.fetchone()["m"] or 0
        # setval(seq, n)：下一个 nextval 给 n+1。空表给 1 会让首个 id = 2，用 setval 的
        # 三参数形式（is_called=false）让空表下一个就是 1。
        cur.execute("SELECT setval(%s, %s, %s)", (seq, max(mx, 1), mx > 0))
        pc.commit()


# ------------------------------------------------------------------ 对账


def verify(sc, pc, table: str, cols: list[str]) -> dict:
    order = order_key(sc, table, cols)
    sql_lite = f'SELECT {",".join(cols)} FROM "{table}" ORDER BY {order}'
    sql_pg = f'SELECT {",".join(chr(34) + c + chr(34) for c in cols)} FROM "{table}" ORDER BY {order}'

    lit = list(sc.execute(sql_lite))
    with pc.cursor() as cur:
        cur.execute(sql_pg)
        pgr = cur.fetchall()

    def norm(rows, keyed: bool):
        out = []
        for r in rows:
            if keyed:                      # sqlite3.Row
                out.append([r[c] for c in cols])
            else:                          # dict_row
                out.append([r[c] for c in cols])
        return out

    a, b = norm(lit, True), norm(pgr, False)
    n = min(len(a), len(b))
    fmt_a, fmt_b = hashlib.md5(), hashlib.md5()
    same_rows = 0
    first_diff = None
    for i in range(n):
        ha = _row_hash([_val(v) for v in a[i]])
        hb = _row_hash([_val(v) for v in b[i]])
        fmt_a.update(ha.encode())
        fmt_b.update(hb.encode())
        if ha == hb:
            same_rows += 1
        elif first_diff is None:
            for j, c in enumerate(cols):
                if _val(a[i][j]) != _val(b[i][j]):
                    first_diff = (i, c, _val(a[i][j])[:60], _val(b[i][j])[:60])
                    break
    return {
        "table": table,
        "rows_src": len(a),
        "rows_dst": len(b),
        "digest_src": fmt_a.hexdigest(),
        "digest_dst": fmt_b.hexdigest(),
        "same_rows": same_rows,
        "first_diff": first_diff,
    }


def main() -> int:
    ap = argparse.ArgumentParser(description="SQLite → PostgreSQL 搬运与对账")
    ap.add_argument("--db", default=str(DB_PATH), help="源 SQLite 路径")
    ap.add_argument("--tables", nargs="*", default=None, help="只处理这些表")
    ap.add_argument("--verify-only", action="store_true", help="只对账，不写库")
    ap.add_argument("--skip-truncate", action="store_true", help="不先清空目标表")
    args = ap.parse_args()

    import psycopg
    from psycopg.rows import dict_row

    t0 = time.time()
    sc = sqlite3.connect(f"file:{args.db}?mode=ro", uri=True)
    sc.row_factory = sqlite3.Row
    pc = psycopg.connect(_dsn(), row_factory=dict_row)

    tables = args.tables or sqlite_tables(sc)
    print(f"源库：{args.db}")
    print(f"目标：{_dsn()}")
    print(f"表：{len(tables)} 张  {'（仅对账）' if args.verify_only else ''}")
    print()

    problems = 0
    for t in tables:
        cols_src = sqlite_columns(sc, t)
        if not cols_src:
            print(f"  ! {t}: 源库没有这张表，跳过")
            continue
        cols_dst = pg_columns(pc, t)
        if not cols_dst:
            print(f"  ! {t}: 目标库没有这张表，跳过")
            problems += 1
            continue
        missing = [c for c in cols_src if c not in cols_dst]
        extra = [c for c in cols_dst if c not in cols_src]
        if missing or extra:
            print(f"  ! {t}: 列不一致 —— 源多 {missing} / 目标多 {extra}")

        cols = [c for c in cols_src if c in cols_dst]
        if not args.verify_only:
            if not args.skip_truncate:
                truncate(pc, t)
            n = copy_table(sc, pc, t, cols)
            if IDENTITY_COL in cols:
                reset_sequence(pc, t)
            print(f"  灌入 {t:24s} {n:>7d} 行", end="", flush=True)
        else:
            print(f"  对账 {t:24s} {'':>7s}   ", end="", flush=True)

        v = verify(sc, pc, t, cols)
        ok = (v["rows_src"] == v["rows_dst"] == v["same_rows"])
        print(f"  → 对账 {'一致' if ok else '不一致'} "
              f"(源 {v['rows_src']} / 目标 {v['rows_dst']} / 逐行相同 {v['same_rows']})")
        if not ok:
            problems += 1
            if v["first_diff"]:
                i, c, a, b = v["first_diff"]
                print(f"       首个差异 第{i}行 列{c}: {a!r} != {b!r}")

    print()
    print(f"完成，用时 {time.time() - t0:.1f}s，{problems} 个问题")
    sc.close()
    pc.close()
    return 1 if problems else 0


if __name__ == "__main__":
    raise SystemExit(main())
